"""``soh report``: render the figures and the generated documentation from the result files.

Inputs (all produced by earlier pipeline steps, never recomputed here):

* ``reports/benchmark/summary.json`` and ``predictions.csv`` (``soh benchmark``) - required;
* ``reports/audit/audit.json`` (``soh audit``) - optional;
* ``artifacts/models/*.json`` (``soh train``) - optional;
* ``data/processed/nasa_features.csv`` - optional (indicator scatter only).

Outputs:

* ``reports/figures/*.png`` (see :mod:`battery_soh.reporting.figures`);
* ``docs/RESULTS.md`` - fully generated, do not edit;
* the text between ``<!-- BEGIN:RESULTS -->`` / ``<!-- END:RESULTS -->`` and
  ``<!-- BEGIN:AUDIT -->`` / ``<!-- END:AUDIT -->`` in ``README.md``, only if
  those markers exist; nothing else in the README is touched.

Rendering is deterministic: the same inputs give byte-identical files (no
timestamps of the rendering itself; text is written with LF line endings).
Missing optional inputs skip their figure or section with a warning and a
note in the generated document instead of failing.
"""

from __future__ import annotations

import hashlib
import json
import logging
import math
import re
from collections.abc import Callable, Mapping, Sequence
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Final

import pandas as pd

from battery_soh.config import ProjectPaths, get_paths
from battery_soh.data.protocols import CORE_BATTERIES
from battery_soh.evaluation.benchmark.hashing import (
    BENCHMARK_HASH_SECTIONS,
    PRODUCTION_HASH_SECTIONS,
    UNHASHED_SECTIONS,
    config_hashes,
)
from battery_soh.features.build import load_feature_table
from battery_soh.features.registry import FEATURE_SETS
from battery_soh.models.linear_bundle import (
    MANIFEST_NAME,
    ManifestError,
    verify_manifest,
    write_text_lf,
)
from battery_soh.reporting import figures
from battery_soh.reporting.style import (
    AUDIT_LABELS,
    feature_label,
    feature_set_label,
    model_label,
)

__all__ = [
    "FIGURES",
    "ReportInputs",
    "load_inputs",
    "readme_audit_block",
    "readme_results_block",
    "render_all",
    "render_figures",
    "render_results_markdown",
    "replace_marked_block",
    "update_readme",
]

logger = logging.getLogger(__name__)

#: Figure file names, in the order they appear in the results document.
FIGURES: Final[tuple[str, ...]] = (
    "lobo_trajectories.png",
    "leakage_audit.png",
    "leaderboard.png",
    "coverage.png",
    "window_sweep.png",
    "indicators_vs_soh.png",
    "extended_lobo.png",
    "feature_contributions.png",
)
_GENERATED_NOTE: Final = (
    "<!-- generated by `soh report` from reports/benchmark, reports/audit and artifacts/models; "
    "do not edit -->"
)
#: How to read the config hash next to the pre-specified headline.
_HASH_NOTE: Final = (
    "The configuration hash shows which configuration produced summary.json, not when it was "
    "written; treat this as a commitment made before the headline's own result was computed, "
    "not as a blinded pre-registration."
)
_SET_ORDER: Final[tuple[str, ...]] = (
    "combined",
    "discharge",
    "charge",
    "combined_eis",
    "combined_no_cv",
    "charge_no_cv",
)
_PRODUCTION_ORDER: Final[tuple[str, ...]] = (
    "combined-absolute-ridge",
    "combined-relative-ridge",
    "discharge-absolute-ridge",
    "charge-absolute-ridge",
)


# =========================================================================== inputs


@dataclass(frozen=True)
class ReportInputs:
    """Everything the report reads, loaded once.

    Attributes:
        summary: ``summary.json`` of the benchmark.
        predictions: ``predictions.csv`` (may be empty).
        audit: ``audit.json`` or ``None``.
        bundles: Production bundle documents (may be empty).
        manifest: ``MANIFEST.json`` of the bundles or ``None``.
        table: Feature table or ``None``.
        current_config_sha256: Scoped hash of the benchmark sections of the
            config now on disk (comparable with ``summary.json``'s
            ``config_sha256``), or ``None``.
        current_production_sha256: Scoped hash of the config's ``production``
            section now on disk (comparable with the bundles'
            ``production_config_sha256``), or ``None``.
        current_features_sha256: SHA-256 of the feature CSV now on disk (or ``None``).
    """

    summary: Mapping[str, Any]
    predictions: pd.DataFrame
    audit: Mapping[str, Any] | None = None
    bundles: tuple[Mapping[str, Any], ...] = ()
    manifest: Mapping[str, Any] | None = None
    table: pd.DataFrame | None = None
    current_config_sha256: str | None = None
    current_production_sha256: str | None = None
    current_features_sha256: str | None = None


def _read_json(path: Path) -> Any:
    def _reject(token: str) -> None:
        raise ValueError(f"non-finite number {token} in {path}")

    return json.loads(path.read_text(encoding="utf-8"), parse_constant=_reject)


def _sha256(path: Path) -> str | None:
    return hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None


def load_inputs(paths: ProjectPaths) -> ReportInputs:
    """Load the report inputs from the canonical locations.

    Raises:
        FileNotFoundError: If ``summary.json`` is missing (run ``soh benchmark``).
    """
    summary_path = paths.benchmark_dir / "summary.json"
    if not summary_path.is_file():
        raise FileNotFoundError(f"{summary_path} not found; run `soh benchmark` first")
    summary = _read_json(summary_path)
    pred_path = paths.benchmark_dir / "predictions.csv"
    predictions = pd.read_csv(pred_path) if pred_path.is_file() else pd.DataFrame()
    audit_path = paths.reports / "audit" / "audit.json"
    audit = _read_json(audit_path) if audit_path.is_file() else None
    bundles: list[Mapping[str, Any]] = []
    manifest = None
    manifest_path = paths.models_dir / MANIFEST_NAME
    if manifest_path.is_file():
        try:
            files = verify_manifest(paths.models_dir)
        except ManifestError as exc:  # the API would refuse these bundles too
            logger.warning("model bundles left out of the report: %s", exc)
        else:
            manifest = _read_json(manifest_path)
            for name in sorted(files):
                if "/" not in name and name.endswith(".json"):
                    bundles.append(_read_json(paths.models_dir / name))
    table = None
    if paths.features_csv.is_file():
        table = load_feature_table(paths.features_csv)
    config_rel = (summary.get("provenance") or {}).get("config_path") or "configs/benchmark.yaml"
    config_path = paths.root / str(config_rel)
    hashes: dict[str, str] = {}
    if config_path.is_file():
        try:
            hashes = config_hashes(config_path)
        except ValueError as exc:
            logger.warning("cannot hash %s: %s", config_path, exc)
    return ReportInputs(
        summary=summary,
        predictions=predictions,
        audit=audit,
        bundles=tuple(bundles),
        manifest=manifest,
        table=table,
        current_config_sha256=hashes.get("benchmark"),
        current_production_sha256=hashes.get("production"),
        current_features_sha256=_sha256(paths.features_csv),
    )


# =========================================================================== figures


def _bundle_order(bundles: Sequence[Mapping[str, Any]]) -> list[Mapping[str, Any]]:
    rank = {m: i for i, m in enumerate(_PRODUCTION_ORDER)}
    return sorted(bundles, key=lambda b: (rank.get(str(b["model_id"]), 99), str(b["model_id"])))


def render_figures(inputs: ReportInputs, out_dir: Path) -> dict[str, Path]:
    """Render every figure whose inputs are available.

    Returns:
        ``{file name: path}`` of the figures written (skipped ones are absent).
    """
    summary = inputs.summary
    head = summary.get("headline", {})
    batteries = sorted(
        {str(r["battery_id"]) for r in summary.get("per_battery", [])} or set(CORE_BATTERIES)
    )
    combined = [
        b for b in _bundle_order(inputs.bundles) if b.get("feature_set") == head.get("feature_set")
    ]
    sweep = summary.get("window_sweep") or {}
    extended = summary.get("extended") or {}
    loco = summary.get("loco") or {}
    jobs: dict[str, tuple[bool, Callable[[Path], Path]]] = {
        "lobo_trajectories.png": (
            not inputs.predictions.empty,
            lambda p: figures.lobo_trajectories(inputs.predictions, summary, p),
        ),
        "leakage_audit.png": (
            inputs.audit is not None,
            lambda p: figures.leakage_audit(inputs.audit or {}, p),
        ),
        "leaderboard.png": (
            bool(summary.get("leaderboard")),
            lambda p: figures.leaderboard(summary, p),
        ),
        "coverage.png": (bool(summary.get("coverage")), lambda p: figures.coverage(summary, p)),
        "window_sweep.png": (
            sweep.get("status") == "ok" and bool(sweep.get("windows")),
            lambda p: figures.window_sweep(sweep, p),
        ),
        "indicators_vs_soh.png": (
            inputs.table is not None,
            lambda p: figures.indicators_vs_soh(
                inputs.table if inputs.table is not None else pd.DataFrame(),
                FEATURE_SETS.get(str(head.get("feature_set")), FEATURE_SETS["combined"]),
                p,
                batteries=batteries,
                label=str(summary.get("label", "soh_pct")),
            ),
        ),
        "extended_lobo.png": (
            bool(extended.get("results")),
            lambda p: figures.extended_lobo(extended, loco if loco.get("results") else None, p),
        ),
        "feature_contributions.png": (
            bool(combined),
            lambda p: figures.feature_contributions(combined, p),
        ),
    }
    written: dict[str, Path] = {}
    for name in FIGURES:
        available, build = jobs[name]
        if not available:
            logger.warning("skipping %s: its input is not available", name)
            continue
        written[name] = build(out_dir / name)
        logger.info("wrote %s", written[name])
    return written


# =========================================================================== markdown helpers


def _num(value: Any, digits: int = 2) -> str:
    if value is None or isinstance(value, bool):
        return "n/a"
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "n/a"
    if not math.isfinite(number):
        return "n/a"
    return f"{number:.{digits}f}"


def _signed(value: Any, digits: int = 2) -> str:
    text = _num(value, digits)
    return text if text == "n/a" or text.startswith("-") else f"+{text}"


def _pct(value: Any, digits: int = 1) -> str:
    if value is None:
        return "n/a"
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "n/a"
    return f"{100 * number:.{digits}f}%" if math.isfinite(number) else "n/a"


def _table(header: Sequence[str], rows: Sequence[Sequence[str]], align: str = "") -> list[str]:
    spec = align.ljust(len(header), "l")
    out = [
        "| " + " | ".join(header) + " |",
        "| " + " | ".join("---:" if a == "r" else "---" for a in spec) + " |",
    ]
    out += ["| " + " | ".join(str(c).replace("|", "\\|") for c in row) + " |" for row in rows]
    return out


def _spec(row: Mapping[str, Any]) -> str:
    return f"`{row.get('feature_set')}` / {row.get('mode')} / `{row.get('model')}`"


def _flags(row: Mapping[str, Any]) -> str:
    flags = []
    if row.get("leaky"):
        flags.append("**LEAKY**")
    if row.get("post_hoc"):
        flags.append("post hoc")
    if row.get("headline"):
        flags.append("pre-specified headline")
    return ", ".join(flags)


def _figure(name: str, alt: str, caption: str, figures_written: Mapping[str, Path]) -> list[str]:
    if name not in figures_written:
        return [f"_Figure `{name}` not rendered: its input was not available._", ""]
    return [f"![{alt}](../reports/figures/{name})", "", f"*{caption}*", ""]


def _model_text(model: str) -> str:
    """Model name in prose; plain ``ridge`` is called so, next to the headline's ``ridge_nfs``."""
    return "plain Ridge" if model == "ridge" else model_label(model)


def _relative_name(spec: Mapping[str, Any]) -> str:
    """``"Relative mode, plain Ridge"``: names the model, since two relative rows exist."""
    return f"Relative mode, {_model_text(str(spec.get('model', '')))}"


def _scored_rows_note(head: Mapping[str, Any], rows: Sequence[Mapping[str, Any]]) -> str:
    """Which secondary rows are scored on other cycles than the headline, and why."""
    relative = sorted(
        {int(r["n"]) for r in rows if r.get("mode") == "relative" and r.get("n") is not None}
    )
    abstaining: dict[str, int] = {}
    for r in rows:
        count = int(r.get("n_abstained") or 0)
        if count:
            mode = "" if r.get("mode") == "absolute" else f" ({r.get('mode')})"
            abstaining.setdefault(f"`{r.get('feature_set')}`{mode}", count)
    parts = []
    if relative:
        parts.append(
            "relative " + " / ".join(str(n) for n in relative) + ", reference cycles excluded"
        )
    if abstaining:
        parts.append(
            " / ".join(abstaining)
            + " abstain on "
            + " / ".join(str(n) for n in abstaining.values())
            + " cycles where none of their inputs was measured"
        )
    if not parts:
        return "Same cells, folds and scored cycles as the headline."
    return (
        "Same cells and folds; scored cycles differ (headline "
        f"{head.get('n_cycles', head.get('n', 'n/a'))}; " + "; ".join(parts) + ")."
    )


def _find(rows: Sequence[Mapping[str, Any]], **spec: str) -> Mapping[str, Any] | None:
    for row in rows:
        if all(row.get(k) == v for k, v in spec.items()):
            return row
    return None


# =========================================================================== sections


def _match(then: Any, now: str | None, what: str, command: str) -> str:
    """A recorded hash, compared with the one of the input now on disk."""
    if now is None:
        return f"`{then}`"
    if then == now:
        return f"`{then}` (matches the {what} on disk)"
    return f"`{then}`; the {what} on disk now hashes to `{now}` - re-run `{command}` to refresh"


def _bundle_hashes(bundles: Sequence[Mapping[str, Any]], key: str) -> list[str]:
    """Distinct values of ``provenance[key]`` over the bundles (missing ones skipped)."""
    values = {str((b.get("provenance") or {}).get(key) or "") for b in bundles}
    return sorted(v for v in values if v)


def _production_hash_cell(inputs: ReportInputs) -> str:
    if not inputs.bundles:
        return "n/a (no model bundles)"
    recorded = _bundle_hashes(inputs.bundles, "production_config_sha256")
    if not recorded:
        return "not recorded by the bundles - re-run `soh train`"
    if len(recorded) > 1:
        return (
            "bundles disagree (" + ", ".join(f"`{h}`" for h in recorded) + ") - re-run `soh train`"
        )
    return _match(recorded[0], inputs.current_production_sha256, "production section", "soh train")


def _bundles_cell(inputs: ReportInputs) -> str:
    manifest = inputs.manifest or {}
    text = (
        f"{len(inputs.bundles)} in `artifacts/models` (deterministic timestamp "
        f"{manifest.get('created_utc', 'n/a')}: the feature table's build time unless "
        "`production.created_utc` fixes another, not when `soh train` ran, so reruns are "
        "byte-identical; SHA-256 in `MANIFEST.json`)"
    )
    consumed = _bundle_hashes(inputs.bundles, "benchmark_config_sha256")
    if consumed == [inputs.summary.get("config_sha256")]:
        return text + "; trained on this benchmark run's results (same benchmark config hash)"
    if consumed:
        return (
            text
            + "; trained on results of benchmark config "
            + ", ".join(f"`{h}`" for h in consumed)
            + ", not this run's - re-run `soh train`"
        )
    return text


def _provenance_section(inputs: ReportInputs) -> list[str]:
    s = inputs.summary
    prov = s.get("provenance") or {}
    rows = [
        ["Benchmark run (UTC)", str(s.get("generated_utc", "n/a"))],
        ["Benchmark config", f"`{prov.get('config_path', 'configs/benchmark.yaml')}`"],
        [
            "Config SHA-256, benchmark sections",
            _match(
                s.get("config_sha256"),
                inputs.current_config_sha256,
                "benchmark sections of the config",
                "soh benchmark",
            ),
        ],
        ["Config SHA-256, production section", _production_hash_cell(inputs)],
        [
            "Feature table SHA-256",
            _match(
                s.get("data_sha256"),
                inputs.current_features_sha256,
                "feature table",
                "soh benchmark",
            ),
        ],
        ["Feature extractor version", str(prov.get("feature_extractor_version", "n/a"))],
        ["Package version", str(s.get("package_version", "n/a"))],
        [
            "Environment",
            f"Python {prov.get('python', '?')}, numpy {prov.get('numpy', '?')}, pandas "
            f"{prov.get('pandas', '?')}, scipy {prov.get('scipy', '?')}, scikit-learn "
            f"{prov.get('sklearn', '?')}"
            + (f", matplotlib {prov['matplotlib']}" if prov.get("matplotlib") else "")
            + f" ({prov.get('platform', '?')})",
        ],
        ["Seed", str(prov.get("seed", "n/a"))],
        ["Benchmark runtime", f"{_num(s.get('runtime_s'), 0)} s"],
    ]
    if inputs.audit is not None:
        rows.append(["Audit run (UTC)", str(inputs.audit.get("generated_utc", "n/a"))])
    if inputs.manifest is not None:
        rows.append(["Model bundles", _bundles_cell(inputs)])
    hashed = prov.get("config_sha256_sections") or list(BENCHMARK_HASH_SECTIONS)
    lines = ["## Provenance", ""]
    lines += _table(["Item", "Value"], rows)
    lines += [
        "",
        "The two config hashes are scoped, so each changes only when something it describes "
        "changes: the benchmark hash covers "
        + ", ".join(f"`{k}`" for k in hashed)
        + " (nested `description` text excluded); the production hash covers "
        + ", ".join(f"`{k}`" for k in PRODUCTION_HASH_SECTIONS)
        + ", which only `soh train` reads. Neither covers "
        + ", ".join(f"`{k}`" for k in UNHASHED_SECTIONS)
        + " (file-format version, free text, worker count and file locations; the feature "
        "table's content has its own hash).",
        "",
        "Protocol: whole batteries are held out (leave-one-battery-out, LOBO); feature "
        "selection, penalty tuning and conformal calibration use only the training cells of "
        "each fold. Errors are in SOH percentage points (SOH = 100 x capacity / the cell's own "
        "initial capacity).",
        "",
    ]
    for note in s.get("notes", []):
        lines.append(f"- {note}")
    lines.append("")
    return lines


def _headline_section(inputs: ReportInputs, figs: Mapping[str, Path]) -> list[str]:
    s = inputs.summary
    h = s["headline"]
    pre = s.get("pre_registration") or {}
    per = s.get("per_battery", [])
    rel_spec = s.get("relative_headline") or {}
    lines = ["## Pre-specified headline", ""]
    if pre.get("statement"):
        lines += [f"> {pre['statement']}", ""]
    lines += [_HASH_NOTE, ""]
    lines += _table(
        [
            "Spec",
            "Cells",
            "Cycles",
            "MAE",
            "RMSE",
            "R2 (pooled)",
            "Bias",
            "Worst cell",
            "90% coverage",
            "90% width",
        ],
        [
            [
                _spec(h),
                str(h.get("n_batteries", "")),
                str(h.get("n_cycles", h.get("n", ""))),
                f"**{_num(h.get('mae'))}**",
                _num(h.get("rmse")),
                _num(h.get("r2"), 3),
                _signed(h.get("bias")),
                f"{h.get('worst_battery', '')} ({_num(h.get('worst_mae'))})",
                _pct(h.get("coverage_90")),
                _num(h.get("mean_width_90")),
            ]
        ],
        "lrrrrrrlrr",
    )
    worst = str(h.get("worst_battery", ""))
    w = next((r for r in per if r.get("battery_id") == worst), None)
    others = [
        float(r["mae"]) for r in per if r.get("battery_id") != worst and r.get("mae") is not None
    ]
    if w is not None and others:
        direction = "over" if float(w.get("bias", 0.0)) > 0 else "under"
        rest = sum(others) / len(others)
        lead = (
            "The headline is dominated by one cell"
            if float(w.get("mae", 0.0)) > 2.0 * rest
            else "The worst held-out cell"
        )
        lines += [
            "",
            f"{lead}: held out, {worst} has MAE "
            f"{_num(w.get('mae'))} (the model {direction}-estimates its SOH by "
            f"{_num(abs(float(w.get('bias', 0.0))))} points on average) and 90% coverage "
            f"{_pct(w.get('coverage_90'))}; the other {len(others)} cells average MAE "
            f"{_num(rest)}. This number is reported as pre-specified, "
            "not replaced by a better-looking secondary result.",
        ]
    lines += ["", "Per held-out cell:", ""]
    lines += _per_battery_table(per)
    lines += [""]
    lines += _figure(
        "lobo_trajectories.png",
        "True and predicted SOH of each held-out core cell",
        "True SOH (black), the pre-specified headline prediction with its 90% conformal "
        "interval (blue) and the relative-mode prediction ("
        + (f"{_model_text(str(rel_spec.get('model')))}, " if rel_spec else "")
        + "orange) for each cell held out.",
        figs,
    )
    return lines


def _per_battery_table(per: Sequence[Mapping[str, Any]]) -> list[str]:
    return _table(
        [
            "Held-out cell",
            "Cycles",
            "MAE",
            "RMSE",
            "R2",
            "Bias",
            "Max error",
            "90% cov. (cv)",
            "90% width",
            "90% cov. (cv+)",
        ],
        [
            [
                str(r.get("battery_id")),
                str(r.get("n", "")),
                _num(r.get("mae")),
                _num(r.get("rmse")),
                _num(r.get("r2"), 3),
                _signed(r.get("bias")),
                _num(r.get("max_abs_error")),
                _pct(r.get("coverage_90")),
                _num(r.get("mean_width_90")),
                _pct(r.get("coverage_90_cv_plus")),
            ]
            for r in per
        ],
        "lrrrrrrrrr",
    )


def _secondary_section(inputs: ReportInputs) -> list[str]:
    s = inputs.summary
    rows = []
    h = s["headline"]
    rows.append(
        [
            "Pre-specified headline",
            _spec(h),
            f"**{_num(h.get('mae'))}**",
            _num(h.get("r2"), 3),
            _pct(h.get("coverage_90")),
            _flags(h) or "-",
        ]
    )
    for r in s.get("secondary", []):
        rows.append(
            [
                str(r.get("label", "")),
                _spec(r),
                _num(r.get("mae")),
                _num(r.get("r2"), 3),
                _pct(r.get("coverage_90")),
                _flags(r) or "-",
            ]
        )
    lines = ["## Secondary results", "", _scored_rows_note(h, s.get("secondary", [])), ""]
    lines += _table(
        ["Result", "Spec", "MAE", "R2 (pooled)", "90% coverage", "Flags"], rows, "llrrrl"
    )
    lines += [
        "",
        "Post-hoc rows were defined after the leave-one-battery-out results showed the "
        "constant-voltage duration's cell-specific offset; they are diagnostic ablations, not "
        "valid model selection.",
        "",
    ]
    rel = s.get("relative_headline")
    if rel:
        lines += [
            f"{_relative_name(rel)} ({_spec(rel)}), per held-out cell "
            f"({rel.get('reference_cycles_excluded', 'n/a')} reference cycles not scored):",
            "",
        ]
        lines += _per_battery_table(rel.get("per_battery", []))
        lines += [""]
    return lines


def _baselines_section(inputs: ReportInputs) -> list[str]:
    board = inputs.summary.get("leaderboard", [])
    head = inputs.summary["headline"]
    rows = []
    for mode in ("absolute", "relative"):
        for r in board:
            if (
                r.get("baseline")
                and r.get("mode") == mode
                and r.get("experiment") == head.get("experiment")
            ):
                rows.append(
                    [
                        model_label(str(r["model"])),
                        mode,
                        _num(r.get("mae")),
                        _num(r.get("rmse")),
                        _num(r.get("r2"), 3),
                        "**LEAKY** - sanity check only" if r.get("leaky") else "-",
                    ]
                )
    lines = ["## Baselines", ""]
    lines += _table(["Baseline", "Mode", "MAE", "RMSE", "R2 (pooled)", "Leakage"], rows, "llrrrl")
    lines += [
        "",
        "The capacity oracle uses the label numerator itself; it is not a model, it shows what "
        "the v1 setup was really measuring. In relative mode it divides capacity by the cell's "
        "own reference capacity, which is the label up to the reference definition.",
        "",
    ]
    return lines


def _leaderboard_section(inputs: ReportInputs, figs: Mapping[str, Path]) -> list[str]:
    s = inputs.summary
    head = s["headline"]
    board = pd.DataFrame(s.get("leaderboard", []))
    lines = ["## Leaderboard (core cells, leave-one-battery-out MAE)", ""]
    if board.empty:
        return [*lines, "_No leaderboard in summary.json._", ""]
    models_only = board[~board["baseline"].astype(bool)]
    post = set(models_only.loc[models_only["post_hoc"].astype(bool), "feature_set"])
    present = list(dict.fromkeys(models_only["feature_set"]))
    sets = [x for x in _SET_ORDER if x in present] + sorted(set(present) - set(_SET_ORDER))
    sets = [x for x in sets if x not in post] + [x for x in sets if x in post]
    ref = models_only[
        (models_only["feature_set"] == head["feature_set"]) & (models_only["mode"] == head["mode"])
    ].sort_values("mae")
    models = list(dict.fromkeys([*ref["model"], *sorted(models_only["model"].unique())]))
    for mode in [m for m in ("absolute", "relative") if m in set(models_only["mode"])]:
        part = models_only[models_only["mode"] == mode]
        rows = []
        for model in models:
            cells = [model_label(model)]
            for fs in sets:
                hit = part[(part["model"] == model) & (part["feature_set"] == fs)]
                if hit.empty:
                    cells.append("-")
                    continue
                text = _num(hit["mae"].iloc[0])
                best = float(part[part["feature_set"] == fs]["mae"].min())
                if math.isclose(float(hit["mae"].iloc[0]), best):
                    text = f"**{text}**"
                if model == head["model"] and fs == head["feature_set"] and mode == head["mode"]:
                    text += " (headline)"
                cells.append(text)
            rows.append(cells)
        header = ["Model"] + [
            feature_set_label(fs) + (" (post hoc)" if fs in post else "") for fs in sets
        ]
        lines += [f"### {mode.capitalize()} mode", ""]
        lines += _table(header, rows, "l" + "r" * len(sets))
        lines += [""]
    lines += [
        "Bold = lowest MAE in the column. Columns marked post hoc are diagnostic ablations. "
        f"With {head.get('n_batteries', 'a few')} held-out cells, differences of a few tenths "
        "of a point are within "
        "cell-to-cell noise; picking the best cell of this table would be selection on the test "
        "set, which is why the headline was fixed in advance.",
        "",
    ]
    lines += _figure(
        "leaderboard.png",
        "LOBO MAE by model and feature set",
        "LOBO MAE of every model on the pre-specified feature sets; vertical lines are the "
        "baselines (red: leaky capacity oracle).",
        figs,
    )
    return lines


def _coverage_section(inputs: ReportInputs, figs: Mapping[str, Path]) -> list[str]:
    s = inputs.summary
    lines = ["## Interval coverage", ""]
    blocks = [("Pre-specified headline", s["headline"], s.get("coverage") or [])]
    rel = s.get("relative_headline") or {}
    if rel.get("coverage"):
        blocks.append((_relative_name(rel), rel, rel["coverage"]))
    for name, spec, table in blocks:
        lines += [f"{name} ({_spec(spec)}):", ""]
        lines += _table(
            [
                "Nominal",
                "cv: mean",
                "cv: worst cell",
                "cv: width",
                "cv+: mean",
                "cv+: worst cell",
                "cv+: width",
            ],
            [
                [
                    _pct(t.get("nominal"), 0),
                    _pct(t.get("empirical")),
                    _pct(t.get("min_battery_coverage")),
                    _num(t.get("mean_width")),
                    _pct(t.get("empirical_cv_plus")),
                    _pct(t.get("min_battery_coverage_cv_plus")),
                    _num(t.get("mean_width_cv_plus")),
                ]
                for t in sorted(table, key=lambda t: float(t["nominal"]))
            ],
            "lrrrrrr",
        )
        lines += [""]
    worst = _worst_coverage_cell(s.get("per_battery", []))
    lines += [
        "cv = full-model prediction +/- the conformal quantile of the training cells' pooled "
        "out-of-cell residuals (the construction the model bundles ship); cv+ = group CV+ "
        "(Barber et al. 2021). Means are over held-out cells. Each fold calibrates on three "
        "training cells, and a battery-level finite-sample guarantee at 90% would need at least "
        "nine exchangeable calibration cells, so these coverages are measured, not guaranteed; "
        "a cell unlike all the others can be badly under-covered"
        + (
            f" (headline: {worst[0]} is covered {_pct(worst[1])} of the time at 90%)."
            if worst
            else "."
        ),
        "",
    ]
    lines += _figure(
        "coverage.png",
        "Empirical vs nominal coverage per held-out cell",
        "Empirical coverage of the 80/90/95% intervals on each held-out cell, for the shipped "
        "cv construction and for group CV+.",
        figs,
    )
    return lines


def _worst_coverage_cell(per: Sequence[Mapping[str, Any]]) -> tuple[str, float] | None:
    cov = [
        (str(r["battery_id"]), float(r["coverage_90"]))
        for r in per
        if r.get("coverage_90") is not None
    ]
    return min(cov, key=lambda t: (t[1], t[0])) if cov else None


def _selection_section(inputs: ReportInputs) -> list[str]:
    stab = inputs.summary.get("selection_stability") or {}
    head = stab.get("headline")
    lines = ["## Feature-selection stability (nested selection inside each fold)", ""]
    if head:
        freq = head.get("frequency", {})
        lines += [
            f"Headline spec: mean pairwise Jaccard similarity of the selected sets "
            f"{_num(head.get('mean_pairwise_jaccard'), 2)} over {head.get('n_folds')} folds.",
            "",
        ]
        lines += _table(
            ["Candidate", "Selected in folds"],
            [[f"`{k}` ({feature_label(k)})", _pct(v, 0)] for k, v in freq.items()],
            "lr",
        )
        lines += [""]
        lines += _table(
            ["Held-out cell", "Selected inputs", "alpha", "Inner LOBO MAE"],
            [
                [
                    str(f.get("held_out")),
                    ", ".join(f"`{x}`" for x in f.get("selected", [])),
                    _num(f.get("alpha"), 1),
                    _num(f.get("inner_mae")),
                ]
                for f in head.get("folds", [])
            ],
            "llrr",
        )
        lines += [""]
    specs = stab.get("specs") or {}
    if specs:
        lines += ["Other nested-selection specs:", ""]
        lines += _table(
            ["Spec", "Always selected", "Never selected", "Mean Jaccard"],
            [
                [
                    f"`{sid}`",
                    ", ".join(f"`{x}`" for x in v.get("always_selected", [])) or "-",
                    ", ".join(f"`{x}`" for x in v.get("never_selected", [])) or "-",
                    _num(v.get("mean_pairwise_jaccard"), 2),
                ]
                for sid, v in specs.items()
            ],
            "lllr",
        )
        lines += [""]
    return lines


def _production_section(inputs: ReportInputs, figs: Mapping[str, Path]) -> list[str]:
    lines = ["## Production model bundles", ""]
    if not inputs.bundles:
        return [*lines, "_No bundles in `artifacts/models`; run `soh train`._", ""]
    rows = []
    for b in _bundle_order(inputs.bundles):
        metrics = b.get("metrics", {})
        mean = metrics.get("mean", {})
        q = (b.get("conformal") or {}).get("quantiles", {})
        rows.append(
            [
                f"`{b['model_id']}`",
                ", ".join(f"`{f}`" for f in b["features"]),
                _num(b["estimator"].get("alpha"), 1),
                str((b.get("training") or {}).get("n_cycles", "")),
                _num(mean.get("mae")),
                f"+/- {_num(q.get('0.9'))}" if q.get("0.9") is not None else "unbounded",
                _pct((metrics.get("coverage") or {}).get("0.9")),
                f"[card](../artifacts/models/{b.get('model_card', '')})",
            ]
        )
    lines += _table(
        [
            "Model id",
            "Inputs (after selection)",
            "alpha",
            "Cycles",
            "LOBO MAE",
            "90% interval",
            "90% LOBO coverage",
            "Model card",
        ],
        rows,
        "llrrrrrl",
    )
    lines += [
        "",
        "Each bundle re-runs its evaluated procedure on all of its training cells; its LOBO "
        "metrics "
        "describe that procedure on unseen cells (training refuses to write a bundle whose "
        "per-cell models do not reproduce the benchmark's numbers). The API serves, among the "
        "bundles whose inputs are available, the one with the lowest LOBO MAE.",
        "",
    ]
    lines += _figure(
        "feature_contributions.png",
        "Standardized coefficients of the combined production bundles",
        "Standardized ridge coefficients of the shipped combined bundles; candidates dropped "
        "by the nested selection are marked.",
        figs,
    )
    return lines


def _window_text(w: Mapping[str, Any]) -> str:
    if w.get("kind") == "discharge":
        return f"discharge {float(w['v_high']):.2f} -> {float(w['v_low']):.2f} V"
    return f"charge {float(w['v_start']):.2f} -> {float(w.get('v_end', 4.19)):.2f} V"


def _sweep_best_note(sweep: Mapping[str, Any]) -> list[str]:
    """Name the lowest-MAE window per mode as what it is: the best of N on the same cells."""
    windows = list(sweep.get("windows", []))
    best = sweep.get("lowest_mae_window") or {}
    parts = []
    for mode in ("absolute", "relative"):
        w = next((x for x in windows if x.get("id") == best.get(mode)), None)
        mae = (w or {}).get(mode) or {}
        if w is not None and mae.get("mae") is not None:
            parts.append(f"{mode} {_num(mae['mae'])} ({_window_text(w)})")
    if not parts:
        return []
    return [
        f"Lowest MAE: {'; '.join(parts)}. Each is the best of the {len(windows)} windows "
        "scored on the same cells, so it is an optimistic estimate for a new cell, not a "
        "held-out result; the registry windows were fixed before the sweep and are not "
        "replaced by its winner.",
        "",
    ]


def _window_section(inputs: ReportInputs, figs: Mapping[str, Path]) -> list[str]:
    sweep = inputs.summary.get("window_sweep") or {}
    lines = ["## Window sweep (exploratory)", ""]
    if sweep.get("status") != "ok":
        return [*lines, f"_Not available: {sweep.get('reason', 'not run')}._", ""]
    if sweep.get("note"):
        lines += [str(sweep["note"]), ""]
    rows = []
    for w in sweep.get("windows", []):
        rows.append(
            [
                _window_text(w),
                _pct(w.get("availability"), 0),
                _pct(w.get("capacity_fraction_mean"), 0),
                _num((w.get("absolute") or {}).get("mae")),
                _num((w.get("relative") or {}).get("mae")),
            ]
        )
    lines += _table(
        ["Window", "Cycles measurable", "Capacity covered", "MAE absolute", "MAE relative"],
        rows,
        "lrrrr",
    )
    lines += [""]
    lines += _sweep_best_note(sweep)
    lines += _figure(
        "window_sweep.png",
        "MAE vs share of capacity covered by the measurement window",
        "Single-window indicators: LOBO MAE against the share of the cell's capacity the "
        "window spans. The registry windows were fixed before this sweep.",
        figs,
    )
    return lines


def _extended_section(inputs: ReportInputs, figs: Mapping[str, Path]) -> list[str]:
    ext = inputs.summary.get("extended") or {}
    loco = inputs.summary.get("loco") or {}
    lines = ["## Extended multi-condition set", ""]
    if not ext.get("results"):
        return [*lines, f"_Not available: {ext.get('reason', 'not run')}._", ""]
    conditions = ext.get("conditions", {})
    groups: dict[str, list[str]] = {}
    for b, c in sorted(conditions.items()):
        groups.setdefault(str(c), []).append(str(b))
    lines += [
        f"{len(conditions)} cells in {len(groups)} operating conditions ("
        + "; ".join(f"{c}: {', '.join(bs)}" for c, bs in groups.items())
        + f"), {ext.get('n_qc_valid_cycles', 'n/a')} QC-valid cycles. Relative mode keeps "
        + ", ".join(f"`{f}`" for f in ext.get("relative_keep_absolute", []))
        + " absolute.",
        "",
    ]
    rows = []
    for r in ext["results"]:
        ci = r.get("mae_ci")
        rows.append(
            [
                _spec(r),
                _num(r.get("mae")),
                f"[{_num(ci[0])}, {_num(ci[1])}]" if isinstance(ci, list) and len(ci) == 2 else "-",
                f"{r.get('worst_battery', '')} ({_num(r.get('worst_mae'))})",
                _pct(r.get("coverage_90")),
                str(r.get("n_abstained", 0)),
                _flags(r) or ("baseline" if r.get("baseline") else "-"),
            ]
        )
    lines += _table(
        [
            "Spec",
            "MAE",
            "95% CI (cells resampled)",
            "Worst cell",
            "90% coverage",
            "Abstained cycles",
            "Flags",
        ],
        rows,
        "lrrlrrl",
    )
    wil = ext.get("wilcoxon") or []
    if wil:
        lines += ["", "Paired Wilcoxon signed-rank tests over held-out cells (two-sided):", ""]
        lines += _table(
            [
                "Feature set / mode",
                "Reference",
                "Best candidate",
                "MAE ref.",
                "MAE cand.",
                "Cells where ref. better",
                "p-value",
            ],
            [
                [
                    f"`{w.get('feature_set')}` / {w.get('mode')}",
                    model_label(str(w.get("reference_model"))),
                    model_label(str(w.get("best_candidate"))),
                    _num(w.get("mae_reference")),
                    _num(w.get("mae_best_candidate")),
                    f"{w.get('reference_better_count')} of {w.get('n_pairs')}",
                    _num(w.get("p_value"), 3),
                ]
                for w in wil
            ],
            "lllrrrr",
        )
        note = wil[0].get("selection_note")
        if note:
            lines += ["", f"Note: {note}; the p-values are therefore optimistic for the candidate."]
    lines += [""]
    if loco.get("results"):
        lines += ["### Leave-one-condition-out", ""]
        if loco.get("note"):
            lines += [str(loco["note"]), ""]
        conds = list(loco.get("conditions", {}))
        rows = []
        for r in loco["results"]:
            per = r.get("per_condition") or {}
            rows.append(
                [_spec(r), _num(r.get("mae"))]
                + [_num((per.get(c) or {}).get("mae")) for c in conds]
                + [_flags(r) or ("baseline" if r.get("baseline") else "-")]
            )
        lines += _table(
            ["Spec", "MAE (mean over cells)", *[f"{c} held out" for c in conds], "Flags"],
            rows,
            "l" + "r" * (len(conds) + 1) + "l",
        )
        models = [r for r in loco["results"] if not r.get("baseline") and r.get("mae") is not None]
        base = [r for r in loco["results"] if r.get("baseline") and r.get("mae") is not None]
        if models and base:
            best = min(models, key=lambda r: float(r["mae"]))
            ref = min(base, key=lambda r: float(r["mae"]))
            worse = [r for r in models if float(r["mae"]) > float(ref["mae"])]
            lines += [
                "",
                f"Best leave-one-condition-out result: {_spec(best)}, MAE {_num(best['mae'])}; "
                f"the best baseline ({_spec(ref)}) scores {_num(ref['mae'])}, and {len(worse)} "
                f"of {len(models)} model specs do worse than it. Transfer to an unseen operating "
                "condition is not solved by these indicators.",
            ]
        lines += [""]
    lines += _figure(
        "extended_lobo.png",
        "Per-cell MAE on the extended multi-condition set",
        "Per-cell LOBO MAE on the extended multi-condition set (relative mode, combined "
        "indicators), "
        "grouped by operating condition, and the leave-one-condition-out MAE.",
        figs,
    )
    return lines


def _audit_section(inputs: ReportInputs, figs: Mapping[str, Path]) -> list[str]:
    lines = ["## Leakage audit (v1 vs v2)", ""]
    audit = inputs.audit
    if audit is None:
        return [*lines, "_`reports/audit/audit.json` not found; run `soh audit`._", ""]
    lines += _audit_table(audit)
    overlap = audit.get("contaminated_test_overlap") or {}
    lines += [
        "",
        f"- Within each cell, SOH is an exact linear function of capacity: R2 = "
        f"{_num(audit.get('soh_vs_capacity_within_battery_r2'), 3)}.",
        f"- The v1 full-discharge inputs without capacity still rebuild capacity: LOBO R2 = "
        f"{_num(audit.get('capacity_reconstruction_r2'), 3)}.",
        f"- The v1 'test' set shared {overlap.get('overlapping_rows', 'n/a')} of its "
        f"{overlap.get('test_rows', 'n/a')} rows with the training set.",
        "",
    ]
    lines += _figure(
        "leakage_audit.png",
        "MAE of the v1 evaluations vs the leakage-free v2 results",
        "MAE (bars) and R2 of each evaluation; red rows use label information. The best-looking "
        "number comes from the contaminated split.",
        figs,
    )
    checks = inputs.summary.get("leakage_checks") or {}
    if checks:
        lines += ["Leakage checks run by the benchmark before fitting any v2 feature set:", ""]
        lines += _table(
            [
                "Experiment / feature set",
                "Passed",
                "Max within-cell abs. r with label",
                "Capacity reconstruction LOBO R2",
            ],
            [
                [
                    f"`{k}`",
                    "yes" if v.get("passed") else "**no**",
                    _num(v.get("max_within_battery_abs_r_with_label"), 3),
                    _num(v.get("capacity_reconstruction_lobo_r2"), 3),
                ]
                for k, v in checks.items()
            ],
            "lrrr",
        )
        lines += [
            "",
            "Health indicators legitimately correlate strongly with capacity (that is what makes "
            "them indicators); the checks target exact reconstructions of the label.",
            "",
        ]
    return lines


def _audit_table(audit: Mapping[str, Any]) -> list[str]:
    return _table(
        ["Evaluation", "Category", "MAE", "R2 (pooled)", "Leaky", "Protocol"],
        [
            [
                str(r.get("label", r.get("id"))),
                str(r.get("category", "")),
                _num(r.get("mae")),
                _num(r.get("r2"), 3),
                "**yes**" if r.get("leaky") else "no",
                str(r.get("protocol", "")),
            ]
            for r in audit.get("rows", [])
        ],
        "llrrll",
    )


def _indicator_section(figs: Mapping[str, Path]) -> list[str]:
    return [
        "## Health indicators",
        "",
        *_figure(
            "indicators_vs_soh.png",
            "The four strongest health indicators against SOH",
            "The four combined-set indicators most correlated with SOH within each cell. The "
            "per-cell offsets (for example of the CV phase duration) are what an absolute-mode "
            "model cannot learn from a handful of cells, and what relative mode removes.",
            figs,
        ),
    ]


def render_results_markdown(inputs: ReportInputs, figs: Mapping[str, Path]) -> str:
    """The full ``docs/RESULTS.md`` text (LF line endings, no rendering timestamp)."""
    lines = [
        _GENERATED_NOTE,
        "",
        "# Results",
        "",
        "> Generated by `soh report` from `reports/benchmark/summary.json`, "
        "`reports/audit/audit.json` and `artifacts/models`; do not edit. Regenerate with "
        "`soh benchmark && soh train && soh report`.",
        "",
    ]
    lines += _provenance_section(inputs)
    lines += _headline_section(inputs, figs)
    lines += _secondary_section(inputs)
    lines += _baselines_section(inputs)
    lines += _leaderboard_section(inputs, figs)
    lines += _coverage_section(inputs, figs)
    lines += _selection_section(inputs)
    lines += _production_section(inputs, figs)
    lines += _indicator_section(figs)
    lines += _window_section(inputs, figs)
    lines += _extended_section(inputs, figs)
    lines += _audit_section(inputs, figs)
    text = "\n".join(lines).rstrip("\n") + "\n"
    return re.sub(r"\n{3,}", "\n\n", text)


# =========================================================================== README blocks


def readme_results_block(summary: Mapping[str, Any]) -> str:
    """Compact headline table for the README (headline vs relative vs baselines vs oracle)."""
    h = summary["headline"]
    board = summary.get("leaderboard", [])
    rows = [
        [
            f"Pre-specified headline: {_spec(h)}",
            f"**{_num(h.get('mae'))}**",
            _num(h.get("r2"), 3),
            _pct(h.get("coverage_90")),
            f"worst cell {h.get('worst_battery', '')}: {_num(h.get('worst_mae'))}",
        ]
    ]
    wanted = (
        (
            "combined",
            "relative",
            "ridge_nfs",
            "Relative mode, nested selection (commissioning reference)",
        ),
        ("discharge", "absolute", "ridge", "Discharge window only"),
    )
    for fs, mode, model, label in wanted:
        r = _find(
            board, experiment=str(h.get("experiment")), feature_set=fs, mode=mode, model=model
        )
        if r is not None:
            rows.append(
                [
                    f"{label}: {_spec(r)}",
                    _num(r.get("mae")),
                    _num(r.get("r2"), 3),
                    _pct(r.get("coverage_90")),
                    f"worst cell {r.get('worst_battery', '')}: {_num(r.get('worst_mae'))}",
                ]
            )
    for name, b in (summary.get("baselines") or {}).items():
        label = model_label(str(name)).replace(" (leaky)", "")
        leaky = bool(b.get("leaky"))
        note = "uses the label numerator - sanity check only" if leaky else "baseline"
        rows.append(
            [
                f"**LEAKY:** {label}" if leaky else label,
                _num(b.get("mae")),
                _num(b.get("r2"), 3),
                "-",
                note,
            ]
        )
    lines = _table(
        [
            "Leave-one-battery-out, 4 core cells",
            "MAE (SOH pts)",
            "R2 (pooled)",
            "90% coverage",
            "Note",
        ],
        rows,
        "lrrrl",
    )
    lines += [
        "",
        "Full tables, per-cell results and provenance: [docs/RESULTS.md](docs/RESULTS.md) "
        "(generated by `soh report`).",
    ]
    return "\n".join(lines)


#: Marks README audit rows whose inputs carry label information (explained below the table).
_LEAKY_MARK: Final = "\N{DAGGER}"


def readme_audit_block(audit: Mapping[str, Any]) -> str:
    """Compact leakage-audit table for the README: evaluation, MAE and R^2.

    Three columns with the short labels of
    :data:`~battery_soh.reporting.style.AUDIT_LABELS` (falling back to the row's
    own label), so the table fits GitHub's README width; rows with leaky inputs
    carry a dagger explained in one line under the table. ``docs/RESULTS.md``
    keeps the full table (category, leaky flag, protocol).
    """
    rows = []
    for r in audit.get("rows", []):
        row_id = str(r.get("id", ""))
        label = AUDIT_LABELS.get(row_id) or str(r.get("label", row_id))
        rows.append(
            [
                label + (f" {_LEAKY_MARK}" if r.get("leaky") else ""),
                _num(r.get("mae")),
                _num(r.get("r2"), 3),
            ]
        )
    lines = _table(["Evaluation", "MAE", "R\N{SUPERSCRIPT TWO}"], rows, "lrr")
    lines += [
        "",
        f"{_LEAKY_MARK} Leaky: the inputs contain capacity (the label numerator) or "
        "full-discharge proxies of it. MAE in SOH percentage points (LOBO rows: mean over "
        "held-out cells); R\N{SUPERSCRIPT TWO} pooled over all evaluated cycles. Protocols "
        "and categories: [docs/RESULTS.md](docs/RESULTS.md#leakage-audit-v1-vs-v2).",
    ]
    return "\n".join(lines)


def replace_marked_block(text: str, name: str, block: str) -> str:
    """Replace the text between ``<!-- BEGIN:name -->`` and ``<!-- END:name -->``.

    The markers themselves and everything outside them are kept byte for byte.
    The line ending of the replaced region follows the document's (CRLF if the
    document uses CRLF).

    Returns:
        The updated text, or ``text`` unchanged when the markers are absent.

    Raises:
        ValueError: If the markers are unbalanced, repeated or out of order.
    """
    begin, end = f"<!-- BEGIN:{name} -->", f"<!-- END:{name} -->"
    n_begin, n_end = text.count(begin), text.count(end)
    if n_begin == 0 and n_end == 0:
        return text
    if n_begin != 1 or n_end != 1:
        raise ValueError(f"README must contain exactly one {begin} and one {end}")
    start = text.index(begin) + len(begin)
    stop = text.index(end)
    if stop < start:
        raise ValueError(f"{end} comes before {begin}")
    newline = "\r\n" if "\r\n" in text else "\n"
    body = block.replace("\r\n", "\n").strip("\n").replace("\n", newline)
    return text[:start] + newline + body + newline + text[stop:]


def update_readme(
    readme: Path, summary: Mapping[str, Any], audit: Mapping[str, Any] | None
) -> bool:
    """Refresh the marked README blocks; returns True if the file changed."""
    if not readme.is_file():
        return False
    original = readme.read_bytes().decode("utf-8")
    updated = replace_marked_block(original, "RESULTS", readme_results_block(summary))
    if audit is not None:
        updated = replace_marked_block(updated, "AUDIT", readme_audit_block(audit))
    if updated == original:
        logger.info("README.md: no result markers or nothing to change")
        return False
    readme.write_bytes(updated.encode("utf-8"))
    logger.info("README.md: refreshed the generated blocks")
    return True


# =========================================================================== entry point


def render_all(paths: ProjectPaths | None = None) -> list[Path]:
    """Render the figures, ``docs/RESULTS.md`` and the README blocks.

    Args:
        paths: Project paths (default :func:`battery_soh.config.get_paths`).

    Returns:
        Every file written (figures, the results document, README if changed).

    Raises:
        FileNotFoundError: If the benchmark summary is missing.
    """
    paths = paths or get_paths()
    inputs = load_inputs(paths)
    figs = render_figures(inputs, paths.figures_dir)
    results = paths.docs / "RESULTS.md"
    write_text_lf(results, render_results_markdown(inputs, figs))
    written = [*figs.values(), results]
    if update_readme(paths.root / "README.md", inputs.summary, inputs.audit):
        written.append(paths.root / "README.md")
    return written
